import { fileURLToPath } from 'node:url';
import { defineConfig } from 'vitepress';

// The site is built into the repo's public/ folder, which the API serves as
// static files (src/site.ts), locally and on Vercel. public/ is generated by
// `pnpm build`, not committed.
const outDir = fileURLToPath(new URL('../../public', import.meta.url));

// Heading ids the way GitHub makes them, so `file.md#some-heading` links in the
// docs work both on GitHub and on the site (VitePress' default slugs differ,
// e.g. it drops a leading "11." that GitHub keeps).
const githubSlug = (text: string) =>
  text
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{M}\p{N}\p{Pc} -]/gu, '')
    .replace(/ /g, '-');

export default defineConfig({
  title: 'Wallet Ledger',
  description:
    'A USD wallet on a double-entry ledger: how to move money correctly with NestJS and Postgres.',
  lang: 'en-US',
  outDir,
  cleanUrls: true,
  // Commands in the docs point at a local server (http://localhost:3000).
  ignoreDeadLinks: 'localhostLinks',
  lastUpdated: false,
  // Docs that only make sense in the repo, not on the site.
  srcExclude: ['**/README.md'],
  // Architecture and feature pages carry the diagrams: give them a wider
  // column (theme/custom.css, `.Layout.wide`).
  transformPageData(pageData) {
    if (/^(architecture|features)\//.test(pageData.relativePath)) {
      pageData.frontmatter.pageClass ??= 'wide';
    }
  },
  themeConfig: {
    nav: [
      { text: 'Demo', link: '/demo' },
      { text: 'Architecture', link: '/architecture/' },
      { text: 'Decisions', link: '/decisions/' },
      { text: 'Features', link: '/features/ledger-foundation' },
      { text: 'Roadmap', link: '/requirements/00-ledger-foundation' },
    ],
    sidebar: {
      '/architecture/': [
        {
          text: 'Overview',
          items: [
            { text: 'The big picture', link: '/architecture/' },
            {
              text: 'Accounts and entries',
              link: '/architecture/accounts-and-entries',
            },
            {
              text: 'Deposit and hold states',
              link: '/architecture/state-machines',
            },
            { text: 'Idempotency', link: '/architecture/idempotency' },
            { text: 'Concurrency', link: '/architecture/concurrency' },
            { text: 'Data model', link: '/architecture/data-model' },
          ],
        },
        {
          text: 'Deep dive',
          items: [
            { text: 'The real world', link: '/architecture/real-world' },
            {
              text: 'Inside the Nest app',
              link: '/architecture/nest-internals',
            },
            {
              text: 'postTransaction and traces',
              link: '/architecture/post-transaction',
            },
            {
              text: 'Errors, reconciliation, pagination',
              link: '/architecture/operations',
            },
            { text: 'Testing', link: '/architecture/testing' },
          ],
        },
      ],
      '/decisions/': [
        {
          text: 'Decisions',
          items: [
            { text: 'All records', link: '/decisions/' },
            { text: '0001 · Double-entry ledger', link: '/decisions/0001-double-entry-ledger' },
            { text: '0002 · Integer cents', link: '/decisions/0002-integer-cents' },
            { text: '0003 · Explicit SQL, no ORM', link: '/decisions/0003-explicit-sql-no-orm' },
            { text: '0004 · One transaction per request', link: '/decisions/0004-one-transaction-per-request' },
            { text: '0005 · Idempotency in the transaction', link: '/decisions/0005-idempotency-in-the-transaction' },
            { text: '0006 · Locks in a fixed order', link: '/decisions/0006-pessimistic-locks-in-fixed-order' },
            { text: '0007 · Append-only, fix by reversal', link: '/decisions/0007-append-only-reversals' },
            { text: '0008 · Serverless on Vercel', link: '/decisions/0008-serverless-on-vercel' },
            { text: '0009 · Tests on real Postgres', link: '/decisions/0009-tests-against-real-postgres' },
            { text: '0010 · Docs site with VitePress', link: '/decisions/0010-docs-site-vitepress' },
          ],
        },
      ],
      '/features/': [
        {
          text: 'Features',
          items: [
            { text: 'Ledger foundation', link: '/features/ledger-foundation' },
            { text: 'Demo web page', link: '/features/demo-web' },
            { text: 'Docs site', link: '/features/docs-site' },
          ],
        },
      ],
      '/requirements/': [
        {
          text: 'Requirements',
          items: [
            {
              text: 'Ledger foundation',
              link: '/requirements/00-ledger-foundation',
            },
            { text: 'FX remittances', link: '/requirements/fx-remittances' },
            { text: 'Debit card', link: '/requirements/debit-card' },
          ],
        },
      ],
    },
    outline: { level: [2, 3] },
    search: { provider: 'local' },
    socialLinks: [
      { icon: 'github', link: 'https://github.com/F-Fischer/wallet-ledger' },
    ],
    footer: {
      message:
        'Money is an integer number of cents. Every movement sums to zero.',
    },
  },
  markdown: {
    anchor: { slugify: githubSlug },
    config(md) {
      // ```mermaid blocks become <pre class="mermaid">, drawn in the browser by
      // theme/index.ts. v-pre stops Vue from reading {{ }} in diagram labels.
      const fence = md.renderer.rules.fence!;
      md.renderer.rules.fence = (tokens, idx, options, env, self) => {
        const token = tokens[idx];
        if (token.info.trim() === 'mermaid') {
          return `<pre class="mermaid" v-pre>${md.utils.escapeHtml(token.content)}</pre>`;
        }
        return fence(tokens, idx, options, env, self);
      };
    },
  },
});
